examples.template:
VStack(alignment: .leading, spacing: 4) {
    MonarchMyStatus(
        {{people.0.name}},
        url: nil,
        presence: {{people.0.presence|case}},
        customStatus: MonarchMyStatusCustomStatus({{people.0.customStatus.text}}, emoji: {{people.0.customStatus.emoji}}),
        now: {{now|date}}
    ) {}
    MonarchMyStatus(
        {{people.1.name}},
        url: nil,
        presence: {{people.1.presence|case}},
        now: {{now|date}}
    ) {}
    MonarchMyStatus(
        {{people.2.name}},
        url: nil,
        presence: {{people.2.presence|case}},
        now: {{now|date}}
    ) {}
}

examples.code:
VStack(alignment: .leading, spacing: 4) {
    MonarchMyStatus(
        "Ada Lovelace",
        url: nil,
        presence: .online,
        customStatus: MonarchMyStatusCustomStatus("In a workshop until 3pm", emoji: "📅"),
        now: Date(timeIntervalSince1970: 1_772_445_600)
    ) {}
    MonarchMyStatus(
        "Grace Hopper",
        url: nil,
        presence: .away,
        now: Date(timeIntervalSince1970: 1_772_445_600)
    ) {}
    MonarchMyStatus(
        "Alan Turing",
        url: nil,
        presence: .online,
        now: Date(timeIntervalSince1970: 1_772_445_600)
    ) {}
}
